114	// referenceTimeStats is an independent oracle: it derives the full TimeStats
115	// from an explicitly supplied, complete ordered chain rather than from the
116	// index under test, so a shared bug in QueryTimeStats cannot make an
117	// expectation match itself.
118	func referenceTimeStats(chain []Block, q TimeStatsQuery) TimeStats {
119		tip := int64(len(chain))
120		from := q.From
121		if from == 0 {
122			from = 1
123		}
124		to := q.To
125		if to == 0 || to > tip {
126			to = tip
127		}
128		width := q.End - q.Start
129		count := width / q.StepSeconds
130		if width%q.StepSeconds != 0 {
131			count++
132		}
133		stats := TimeStats{
134			Buckets:    make([]TimeBucket, count),
135			FromHeight: from,
136			ToHeight:   to,
137		}
138		for i := range stats.Buckets {
139			stats.Buckets[i].Start = q.Start + q.StepSeconds*int64(i)
140			end := q.Start + q.StepSeconds*(int64(i)+1)
141			if end > q.End {
142				end = q.End
143			}
144			stats.Buckets[i].End = end
145		}
146		if from > to {
147			return stats
148		}
149		var filter map[string]struct{}
150		if len(q.TxIDs) > 0 {
151			filter = map[string]struct{}{}
152			for _, id := range q.TxIDs {
153				filter[id] = struct{}{}
154			}
155		}
156		type acc struct {
157			occ    int64
158			ids    map[string]struct{}
159			blocks int64
160		}
161		per := make([]acc, count)
162		windowIDs := map[string]struct{}{}
163		for height := from; height <= to; height++ {
164			block := chain[height-1]
165			if block.Time == nil {
166				stats.MissingTimeBlocks++
167				continue
168			}
169			t := *block.Time
170			if t < q.Start || t >= q.End {
171				continue
172			}
173			bucket := (t - q.Start) / q.StepSeconds
174			matched := false
175			for _, tx := range block.Txs {
176				if filter != nil {
177					if _, ok := filter[tx]; !ok {
178						continue
179					}
180				}
181				stats.Totals.TxCount++
182				per[bucket].occ++
183				if per[bucket].ids == nil {
184					per[bucket].ids = map[string]struct{}{}
185				}
186				per[bucket].ids[tx] = struct{}{}
187				windowIDs[tx] = struct{}{}
188				matched = true
189			}
190			if matched {
191				per[bucket].blocks++
192				stats.Totals.Blocks++
193			}
194		}
195		for i := range per {
196			stats.Buckets[i].TxCount = per[i].occ
197			stats.Buckets[i].DistinctTxIDs = int64(len(per[i].ids))
198			stats.Buckets[i].Blocks = per[i].blocks
199		}
200		stats.Totals.DistinctTxIDs = int64(len(windowIDs))
201		return stats
202	}
