364	// Installs one-shot rendezvous hooks and guarantees they are removed.
365	type reorgStatsHooks struct {
366		queryParked   chan struct{}
367		releaseQuery  chan struct{}
368		reorgParked   chan struct{}
369		releaseReorg  chan struct{}
370		queryHookOnce sync.Once
371		reorgHookOnce sync.Once
372	}
373	
374	func installReorgStatsHooks(t *testing.T) *reorgStatsHooks {
375		t.Helper()
376		h := &reorgStatsHooks{
377			queryParked:  make(chan struct{}),
378			releaseQuery: make(chan struct{}),
379			reorgParked:  make(chan struct{}),
380			releaseReorg: make(chan struct{}),
381		}
382		statsQueryHookLocked = func(to int64) {
383			h.queryHookOnce.Do(func() { close(h.queryParked) })
384			<-h.releaseQuery
385		}
386		reorgAppliedHookLocked = func(newTip int64) {
387			if newTip != 4 {
388				t.Errorf("reorg hook saw newTip=%d, want 4", newTip)
389			}
390			h.reorgHookOnce.Do(func() { close(h.reorgParked) })
391			<-h.releaseReorg
392		}
393		t.Cleanup(func() {
394			statsQueryHookLocked = nil
395			reorgAppliedHookLocked = nil
396		})
397		return h
398	}
