488	// The validator must actually catch old/new mixtures — including ones where
489	// the per-bucket occurrence counts still sum to the window total.
490	func TestClassifyTimeStatsRejectsMixedAndCorruptReturns(t *testing.T) {
491		oldRef, newRef := literalOldStats(), literalNewStats()
492		if err := classifyTimeStats(oldRef, oldRef, newRef); err != nil {
493			t.Fatalf("pure old answer rejected: %v", err)
494		}
495		if err := classifyTimeStats(newRef, oldRef, newRef); err != nil {
496			t.Fatalf("pure new answer rejected: %v", err)
497		}
498	
499		// Mixture 1: new-chain buckets and totals but the stale OLD upper height
500		// and missing-time count. Bucket occurrences sum to the total, so the
501		// naive sum check accepts it; the complete-chain check must not.
502		mixed1 := newRef
503		mixed1.ToHeight = oldRef.ToHeight
504		mixed1.MissingTimeBlocks = oldRef.MissingTimeBlocks
505		if !bucketOccurrenceSumEqualsTotal(mixed1) {
506			t.Fatal("test setup: mixed1 is meant to pass the weak sum check")
507		}
508		if err := classifyTimeStats(mixed1, oldRef, newRef); err == nil {
509			t.Fatal("new-chain counts under the old tip height were accepted")
510		} else if !strings.Contains(err.Error(), "MIXED") {
511			t.Fatalf("mixed1 not reported as MIXED:\n%v", err)
512		}
513	
514		// Mixture 2: old-chain buckets and totals but the NEW shortened upper
515		// height — claims tip 4 while still counting removed height 5's f.
516		mixed2 := oldRef
517		mixed2.ToHeight = newRef.ToHeight
518		if !bucketOccurrenceSumEqualsTotal(mixed2) {
519			t.Fatal("test setup: mixed2 is meant to pass the weak sum check")
520		}
521		if err := classifyTimeStats(mixed2, oldRef, newRef); err == nil {
522			t.Fatal("old-chain counts under the new tip height were accepted")
523		} else if !strings.Contains(err.Error(), "MIXED") {
524			t.Fatalf("mixed2 not reported as MIXED:\n%v", err)
525		}
526	
527		// Mixture 3: new range and missing count but old per-bucket shape and a
528		// stitched total — cross-component mix with no consistent sum.
529		mixed3 := newRef
530		mixed3.Buckets = oldRef.Buckets
531		mixed3.Totals.TxCount = oldRef.Totals.TxCount
532		if err := classifyTimeStats(mixed3, oldRef, newRef); err == nil {
533			t.Fatal("old buckets against the new range were accepted")
534		} else if !strings.Contains(err.Error(), "MIXED") {
535			t.Fatalf("mixed3 not reported as MIXED:\n%v", err)
536		}
537	
538		// Corruption that belongs to neither chain must also be rejected.
539		corrupt := newRef
540		corrupt.Buckets[0].TxCount++
541		corrupt.Totals.TxCount++
542		if err := classifyTimeStats(corrupt, oldRef, newRef); err == nil {
543			t.Fatal("corrupt answer matching neither chain was accepted")
544		}
545	}
