547	// Sustained overlap: reorgs alternate between the old and the shortened new
548	// branch while readers query continuously. Every answer must classify as one
549	// complete chain; success never depends on which side of the reorg a query
550	// happened to land. Deterministic, offline, and timing-independent — a torn
551	// answer fails regardless of scheduling.
552	func TestQueryTimeStatsRepeatedShorteningReorgsStayConsistent(t *testing.T) {
553		index := buildOldChain(t)
554		oldRef, newRef := literalOldStats(), literalNewStats()
555		oldBranch := reorgOldChainBlocks()[2:] // h3,h4,h5 rooted at h2, restores tip 5
556	
557		const reorgers = 2
558		const rounds = 40
559		const readers = 4
560		const reads = 80
561	
562		stop := make(chan struct{})
563		var wg sync.WaitGroup
564		for r := 0; r < reorgers; r++ {
565			wg.Add(1)
566			go func(seed int) {
567				defer wg.Done()
568				for i := 0; i < rounds; i++ {
569					select {
570					case <-stop:
571						return
572					default:
573					}
574					branch := reorgNewBranch()
575					if (i+seed)%2 == 0 {
576						branch = oldBranch
577					}
578					if _, err := index.Reorg(branch); err != nil {
579						t.Errorf("reorg failed: %v", err)
580						return
581					}
582				}
583			}(r)
584		}
585		for r := 0; r < readers; r++ {
586			wg.Add(1)
587			go func() {
588				defer wg.Done()
589				for i := 0; i < reads; i++ {
590					select {
591					case <-stop:
592						return
593					default:
594					}
595					stats, err := index.QueryTimeStats(reorgStatsQuery)
596					if err != nil {
597						t.Errorf("query failed: %v", err)
598						return
599					}
600					if err := classifyTimeStats(stats, oldRef, newRef); err != nil {
601						t.Errorf("%v", err)
602						return
603					}
604				}
605			}()
606		}
607		wg.Wait()
608		close(stop)
609	
610		// Leave the index deterministically on the new chain and re-verify.
611		if _, err := index.Reorg(reorgNewBranch()); err != nil {
612			t.Fatalf("final reorg failed: %v", err)
613		}
614		final, err := index.QueryTimeStats(reorgStatsQuery)
615		if err != nil {
616			t.Fatal(err)
617		}
618		if !reflect.DeepEqual(final, newRef) {
619			t.Fatalf("final state is not the complete new chain:\n%+v", final)
620		}
621	}
