11	// txChain builds a chain with one block per tx list, hashes h1..hN.
12	func txChain(t *testing.T, txs ...[]string) *Index {
13		t.Helper()
14		index := New()
15		for i, blockTxs := range txs {
16			height := int64(i + 1)
17			parent := "genesis"
18			if height > 1 {
19				parent = fmt.Sprintf("h%d", height-1)
20			}
21			block := Block{Height: height, Hash: fmt.Sprintf("h%d", height), Parent: parent, Txs: blockTxs}
22			if err := index.Append(block); err != nil {
23				t.Fatalf("setup append at height %d: %v", height, err)
24			}
25		}
26		return index
27	}
