170		if err := restored.Restore(strings.NewReader(raw)); err != nil {
171			t.Fatalf("restore of pinned snapshot failed: %v", err)
172		}
173		if restored.Blocks[1].Time != nil {
174			t.Fatalf("height 1 time=%v, want missing", restored.Blocks[1].Time)
175		}
