215		// A second export after the reorg reflects only the new, fully untimed
216		// chain: version 1, no timestamp field anywhere, tip and hashes new.
217		wantNewSnapshot := `{"version":1,"tip":4,"blocks":[` +
218			`{"height":1,"hash":"old-a","parent":"genesis","txs":["dup",""]},` +
219			`{"height":2,"hash":"new-b","parent":"old-a","txs":["new-tx","","new-tx"]},` +
220			`{"height":3,"hash":"new-c","parent":"new-b","txs":["after"]},` +
